const API_URL = process.env.NEXT_PUBLIC_API_URL;

// Error khusus supaya kita tahu kode status (400, 401, 422, dll.)
export class ApiError extends Error {
  constructor(message, status) {
    super(message);
    this.status = status;
  }
}

// Mengubah berbagai bentuk error backend menjadi teks yang mudah dibaca
function extractMessage(data, fallback) {
  if (!data || !data.detail) return fallback;

  // Bentuk 1: "detail" berupa teks. Contoh: "Email sudah terdaftar"
  if (typeof data.detail === "string") return data.detail;

  // Bentuk 2: "detail" berupa daftar (error validasi 422 di dokumentasi)
  if (Array.isArray(data.detail)) {
    return data.detail
      .map((item) => {
        const field = Array.isArray(item.loc) ? item.loc[item.loc.length - 1] : "";
        return field ? `${field}: ${item.msg}` : item.msg;
      })
      .join("\n");
  }

  return fallback;
}

export async function apiFetch(path, { method = "GET", body, token } = {}) {
  const headers = {};
  if (body) headers["Content-Type"] = "application/json";
  if (token) headers["Authorization"] = `Bearer ${token}`;

  let response;
  try {
    response = await fetch(`${API_URL}${path}`, {
      method,
      headers,
      body: body ? JSON.stringify(body) : undefined,
      cache: "no-store",
    });
  } catch {
    throw new ApiError("Tidak dapat terhubung ke server. Pastikan backend sudah berjalan.", 0);
  }

  let data = null;
  try {
    data = await response.json();
  } catch {
    data = null;
  }

  if (!response.ok) {
    throw new ApiError(extractMessage(data, "Terjadi kesalahan pada server."), response.status);
  }

  return data;
}
